    /// <summary>The (LEFT, RIGHT) horizontal skyline pair for an accidental kind,
    /// in the glyph's own frame (X from the glyph origin, Y centred on the note),
    /// out of the <paramref name="design"/> design's outline — 20 by default,
    /// which is what a grob with no font-size reads.</summary>
    /// <remarks>⚠️ PASS THE DESIGN THE METRICS CAME FROM. A glyph's box
    /// (DesignMetrics) and its skyline are two readings of ONE face; taking them from
    /// different designs is the metric-versus-ink split, and it is invisible in both
    /// halves separately. DesignMetrics.Rounded is the number to pass.</remarks>
    public static (HorizontalSkyline Left, HorizontalSkyline Right) AccidentalSkylinePair(string kind, int design = 20) => design switch
    {
        11 => kind switch
        {
            "sharp" => (AccSkyPairSharp11.Left, AccSkyPairSharp11.Right),
            "flat" => (AccSkyPairFlat11.Left, AccSkyPairFlat11.Right),
            "natural" => (AccSkyPairNatural11.Left, AccSkyPairNatural11.Right),
            "doubleSharp" => (AccSkyPairDoubleSharp11.Left, AccSkyPairDoubleSharp11.Right),
            "doubleFlat" => (AccSkyPairDoubleFlat11.Left, AccSkyPairDoubleFlat11.Right),
            _ => (AccSkyPairNatural11.Left, AccSkyPairNatural11.Right),
        },
        13 => kind switch
        {
            "sharp" => (AccSkyPairSharp13.Left, AccSkyPairSharp13.Right),
            "flat" => (AccSkyPairFlat13.Left, AccSkyPairFlat13.Right),
            "natural" => (AccSkyPairNatural13.Left, AccSkyPairNatural13.Right),
            "doubleSharp" => (AccSkyPairDoubleSharp13.Left, AccSkyPairDoubleSharp13.Right),
            "doubleFlat" => (AccSkyPairDoubleFlat13.Left, AccSkyPairDoubleFlat13.Right),
            _ => (AccSkyPairNatural13.Left, AccSkyPairNatural13.Right),
        },
        14 => kind switch
        {
            "sharp" => (AccSkyPairSharp14.Left, AccSkyPairSharp14.Right),
            "flat" => (AccSkyPairFlat14.Left, AccSkyPairFlat14.Right),
            "natural" => (AccSkyPairNatural14.Left, AccSkyPairNatural14.Right),
            "doubleSharp" => (AccSkyPairDoubleSharp14.Left, AccSkyPairDoubleSharp14.Right),
            "doubleFlat" => (AccSkyPairDoubleFlat14.Left, AccSkyPairDoubleFlat14.Right),
            _ => (AccSkyPairNatural14.Left, AccSkyPairNatural14.Right),
        },
        16 => kind switch
        {
            "sharp" => (AccSkyPairSharp16.Left, AccSkyPairSharp16.Right),
            "flat" => (AccSkyPairFlat16.Left, AccSkyPairFlat16.Right),
            "natural" => (AccSkyPairNatural16.Left, AccSkyPairNatural16.Right),
