            "doubleFlat" => (AccSkyPairDoubleFlat16.Left, AccSkyPairDoubleFlat16.Right),
            _ => (AccSkyPairNatural16.Left, AccSkyPairNatural16.Right),
        },
        18 => kind switch
        {
            "sharp" => (AccSkyPairSharp18.Left, AccSkyPairSharp18.Right),
            "flat" => (AccSkyPairFlat18.Left, AccSkyPairFlat18.Right),
            "natural" => (AccSkyPairNatural18.Left, AccSkyPairNatural18.Right),
